-- SAVEAT MVP — eseguire tutto in una query nel SQL Editor di Supabase.
-- Nessuna tabella esistente viene eliminata. Nomi dedicati saveat_*.
begin;
create table if not exists public.saveat_profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 display_name text not null default '' check(length(display_name)<=100),
 account_type text check(account_type in ('private','business')),
 business_name text not null default '' check(length(business_name)<=150),
 created_at timestamptz not null default now()
);
create table if not exists public.saveat_municipalities (
 code text primary key, name text not null, province text not null,
 unique(name,province)
);
create index if not exists saveat_municipality_search on public.saveat_municipalities(lower(name) text_pattern_ops);
create table if not exists public.saveat_listings (
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references public.saveat_profiles(id),
 seller_name text not null, account_type text not null check(account_type in ('private','business')),
 title text not null check(length(title) between 2 and 120),
 description text not null default '' check(length(description)<=2000),
 municipality_code text not null references public.saveat_municipalities(code),
 pickup_start timestamptz not null, pickup_end timestamptz not null,
 status text not null default 'active' check(status in ('active','closed')),
 created_at timestamptz not null default now(),
 check(pickup_end>pickup_start)
);
create index if not exists saveat_listings_location on public.saveat_listings(municipality_code,status,pickup_end);
create index if not exists saveat_listings_owner on public.saveat_listings(owner_id);
create table if not exists public.saveat_items (
 id uuid primary key default gen_random_uuid(), listing_id uuid not null references public.saveat_listings(id),
 name text not null check(length(name) between 2 and 120),
 unit text not null check(unit in ('pezzi','confezioni','kg','litri')),
 quantity numeric(10,3) not null check(quantity>0 and quantity<10000000),
 available numeric(10,3) not null check(available>=0 and available<=quantity),
 price numeric(10,2) not null default 0 check(price>=0 and price<100000000),
 label_date date, date_type text not null check(date_type in ('use_by','best_before','none')),
 allergens text not null default '' check(length(allergens)<=500),
 photo_path text check(length(photo_path)<=300),
 check(date_type='none' or label_date is not null)
);
create index if not exists saveat_items_listing on public.saveat_items(listing_id);
-- Indirizzo e contatto separati dai dati pubblici.
create table if not exists public.saveat_pickup (
 listing_id uuid primary key references public.saveat_listings(id),
 address text not null check(length(address) between 3 and 300),
 contact text not null check(length(contact) between 3 and 200),
 instructions text not null default '' check(length(instructions)<=1000)
);
create table if not exists public.saveat_reservations (
 id uuid primary key default gen_random_uuid(),
 listing_id uuid not null references public.saveat_listings(id),
 customer_id uuid not null references public.saveat_profiles(id),
 request_id uuid not null,
 status text not null default 'reserved' check(status in ('reserved','confirmed','collected','cancelled','expired')),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(customer_id,request_id)
);
create index if not exists saveat_reservations_customer on public.saveat_reservations(customer_id);
create index if not exists saveat_reservations_listing on public.saveat_reservations(listing_id,status);
create table if not exists public.saveat_reservation_items (
 reservation_id uuid not null references public.saveat_reservations(id),
 item_id uuid not null references public.saveat_items(id),
 name text not null, unit text not null,
 quantity numeric(10,3) not null check(quantity>0), price numeric(10,2) not null check(price>=0),
 primary key(reservation_id,item_id)
);

alter table public.saveat_profiles enable row level security;
alter table public.saveat_municipalities enable row level security;
alter table public.saveat_listings enable row level security;
alter table public.saveat_items enable row level security;
alter table public.saveat_pickup enable row level security;
alter table public.saveat_reservations enable row level security;
alter table public.saveat_reservation_items enable row level security;

-- Solo lettura diretta; tutte le mutazioni passano da funzioni controllate.
revoke all on public.saveat_profiles,public.saveat_municipalities,public.saveat_listings,public.saveat_items,public.saveat_pickup,public.saveat_reservations,public.saveat_reservation_items from anon,authenticated;
grant select on public.saveat_municipalities,public.saveat_listings,public.saveat_items to anon,authenticated;
grant select on public.saveat_profiles,public.saveat_pickup,public.saveat_reservations,public.saveat_reservation_items to authenticated;

drop policy if exists saveat_profile_read on public.saveat_profiles;
create policy saveat_profile_read on public.saveat_profiles for select to authenticated using(id=(select auth.uid()));
drop policy if exists saveat_city_read on public.saveat_municipalities;
create policy saveat_city_read on public.saveat_municipalities for select to anon,authenticated using(true);
drop policy if exists saveat_listing_read on public.saveat_listings;
create or replace function public.saveat_has_reservation(p_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.saveat_reservations where listing_id=p_id and customer_id=auth.uid());
$$;
create policy saveat_listing_read on public.saveat_listings for select to anon,authenticated using(
 (status='active' and pickup_end>now()) or owner_id=(select auth.uid()) or public.saveat_has_reservation(id)
);
-- Helper evita cicli RLS tra annunci e prenotazioni; restituisce solo un booleano.
create or replace function public.saveat_owns_listing(p_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.saveat_listings where id=p_id and owner_id=auth.uid());
$$;
drop policy if exists saveat_item_read on public.saveat_items;
create policy saveat_item_read on public.saveat_items for select to anon,authenticated using(exists(select 1 from public.saveat_listings l where l.id=listing_id));
drop policy if exists saveat_reservation_read on public.saveat_reservations;
create policy saveat_reservation_read on public.saveat_reservations for select to authenticated using(customer_id=(select auth.uid()) or public.saveat_owns_listing(listing_id));
drop policy if exists saveat_reserved_item_read on public.saveat_reservation_items;
create policy saveat_reserved_item_read on public.saveat_reservation_items for select to authenticated using(exists(select 1 from public.saveat_reservations r where r.id=reservation_id));
drop policy if exists saveat_pickup_read on public.saveat_pickup;
create policy saveat_pickup_read on public.saveat_pickup for select to authenticated using(public.saveat_owns_listing(listing_id) or exists(
 select 1 from public.saveat_reservations r join public.saveat_listings l on l.id=r.listing_id
 where r.listing_id=saveat_pickup.listing_id and r.customer_id=(select auth.uid())
 and r.status in ('reserved','confirmed') and l.pickup_end>now()
));

create or replace function public.saveat_new_user() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into public.saveat_profiles(id) values(new.id) on conflict do nothing;
 return new;
end; $$;
drop trigger if exists saveat_auth_user on auth.users;
create trigger saveat_auth_user after insert on auth.users for each row execute function public.saveat_new_user();
insert into public.saveat_profiles(id) select id from auth.users on conflict do nothing;

create or replace function public.saveat_set_profile(p_name text,p_type text,p_business text default '') returns void
language plpgsql security definer set search_path='' as $$
declare v_profile public.saveat_profiles;
begin
 if auth.uid() is null then raise exception 'Accedi per continuare'; end if;
 select * into v_profile from public.saveat_profiles where id=auth.uid() for update;
 if p_type not in ('private','business') or p_type is null or length(trim(p_name)) not between 2 and 100 then raise exception 'Profilo non valido'; end if;
 if v_profile.account_type is not null and v_profile.account_type<>p_type then raise exception 'Il tipo di account non può essere modificato'; end if;
 if p_type='business' and length(trim(p_business)) not between 2 and 150 then raise exception 'Indica il nome dell’attività'; end if;
 update public.saveat_profiles set display_name=trim(p_name),account_type=p_type,business_name=case when p_type='business' then trim(p_business) else '' end where id=auth.uid();
end; $$;

create or replace function public.saveat_create_listing(p_listing jsonb,p_items jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_profile public.saveat_profiles; v_id uuid; v_item jsonb; v_price numeric; v_qty numeric; v_end timestamptz; v_start timestamptz;
begin
 if auth.uid() is null then raise exception 'Accedi per pubblicare'; end if;
 select * into v_profile from public.saveat_profiles where id=auth.uid();
 if v_profile.account_type is null then raise exception 'Completa il profilo'; end if;
 if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 20 then raise exception 'Inserisci da 1 a 20 prodotti'; end if;
 v_start:=(p_listing->>'pickup_start')::timestamptz; v_end:=(p_listing->>'pickup_end')::timestamptz;
 if v_start is null or v_end is null or v_end<=now() or v_end<=v_start or v_end>now()+interval '30 days' then raise exception 'Fascia di ritiro non valida (massimo 30 giorni)'; end if;
 insert into public.saveat_listings(owner_id,seller_name,account_type,title,description,municipality_code,pickup_start,pickup_end)
 values(auth.uid(),case when v_profile.account_type='business' then v_profile.business_name else v_profile.display_name end,v_profile.account_type,
 trim(p_listing->>'title'),coalesce(p_listing->>'description',''),p_listing->>'municipality_code',v_start,v_end) returning id into v_id;
 insert into public.saveat_pickup(listing_id,address,contact,instructions) values(v_id,trim(p_listing->>'address'),trim(p_listing->>'contact'),coalesce(p_listing->>'instructions',''));
 for v_item in select value from jsonb_array_elements(p_items) loop
  v_price:=coalesce((v_item->>'price')::numeric,0); v_qty:=(v_item->>'quantity')::numeric;
  if v_qty is null or v_qty<=0 or v_qty<>round(v_qty,3) or v_price<>round(v_price,2) then raise exception 'Quantità o prezzo non validi'; end if;
  if v_item->>'unit' in ('pezzi','confezioni') and v_qty<>trunc(v_qty) then raise exception 'Usa quantità intere per pezzi e confezioni'; end if;
  if v_item->>'date_type'='use_by' and (v_item->>'label_date')::date < (v_end at time zone 'Europe/Rome')::date then raise exception 'Il ritiro deve avvenire entro la data di scadenza'; end if;
  if nullif(v_item->>'photo_path','') is not null and not exists(select 1 from storage.objects where bucket_id='saveat-photos' and name=v_item->>'photo_path' and split_part(name,'/',1)=auth.uid()::text) then raise exception 'Foto non valida'; end if;
  insert into public.saveat_items(listing_id,name,unit,quantity,available,price,label_date,date_type,allergens,photo_path)
  values(v_id,trim(v_item->>'name'),v_item->>'unit',v_qty,v_qty,v_price,(nullif(v_item->>'label_date',''))::date,v_item->>'date_type',coalesce(v_item->>'allergens',''),nullif(v_item->>'photo_path',''));
 end loop;
 return v_id;
end; $$;

create or replace function public.saveat_reserve(p_listing_id uuid,p_items jsonb,p_request_id uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_listing public.saveat_listings; v_id uuid; v_item public.saveat_items; v_request jsonb; v_qty numeric;
begin
 if auth.uid() is null then raise exception 'Accedi per prenotare'; end if;
 if p_request_id is null or p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 20 then raise exception 'Prenotazione non valida'; end if;
 -- Lock per annuncio: controlli, disponibilità e inserimenti nella stessa transazione.
 select * into v_listing from public.saveat_listings where id=p_listing_id for update;
 if not found then raise exception 'Annuncio non trovato'; end if;
 select id into v_id from public.saveat_reservations where customer_id=auth.uid() and request_id=p_request_id;
 if v_id is not null then
  if not exists(select 1 from public.saveat_reservations where id=v_id and listing_id=p_listing_id) then raise exception 'Richiesta già utilizzata'; end if;
  return v_id;
 end if;
 if v_listing.owner_id=auth.uid() then raise exception 'Non puoi prenotare il tuo annuncio'; end if;
 if v_listing.status<>'active' or v_listing.pickup_end<=now() then raise exception 'Annuncio non più disponibile'; end if;
 if exists(select 1 from jsonb_array_elements(p_items) a group by a->>'item_id' having count(*)>1) then raise exception 'Prodotto duplicato'; end if;
 if exists(select 1 from public.saveat_reservations where listing_id=p_listing_id and customer_id=auth.uid() and status in ('reserved','confirmed')) then raise exception 'Hai già una prenotazione attiva per questo annuncio'; end if;
 insert into public.saveat_reservations(listing_id,customer_id,request_id) values(p_listing_id,auth.uid(),p_request_id) returning id into v_id;
 for v_request in select value from jsonb_array_elements(p_items) loop
  select * into v_item from public.saveat_items where id=(v_request->>'item_id')::uuid and listing_id=p_listing_id for update;
  if not found then raise exception 'Prodotto non trovato'; end if;
  v_qty:=(v_request->>'quantity')::numeric;
  if v_qty is null or v_qty<=0 or v_qty<>round(v_qty,3) or v_qty>v_item.available then raise exception 'Quantità non disponibile'; end if;
  if v_item.unit in ('pezzi','confezioni') and v_qty<>trunc(v_qty) then raise exception 'Usa quantità intere'; end if;
  update public.saveat_items set available=available-v_qty where id=v_item.id;
  insert into public.saveat_reservation_items values(v_id,v_item.id,v_item.name,v_item.unit,v_qty,v_item.price);
 end loop;
 return v_id;
end; $$;

alter table public.saveat_reservations add column if not exists customer_collected_at timestamptz;

create or replace function public.saveat_report_collection(p_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_r public.saveat_reservations; v_l public.saveat_listings; v_listing_id uuid;
begin
 if auth.uid() is null then raise exception 'Accedi per continuare'; end if;
 select listing_id into v_listing_id from public.saveat_reservations where id=p_id;
 select * into v_l from public.saveat_listings where id=v_listing_id for update;
 select * into v_r from public.saveat_reservations where id=p_id for update;
 if v_r.id is null or v_r.customer_id is distinct from auth.uid() then raise exception 'Solo chi prenota può segnalare il ritiro'; end if;
 if v_r.status not in ('reserved','confirmed') then raise exception 'Prenotazione già conclusa'; end if;
 if v_r.customer_collected_at is not null then return; end if;
 if now()<v_l.pickup_start or now()>=v_l.pickup_end then raise exception 'Segnala il ritiro durante la fascia prevista'; end if;
 update public.saveat_reservations set customer_collected_at=now(),updated_at=now() where id=p_id;
end; $$;
revoke all on function public.saveat_report_collection(uuid) from public,anon;
grant execute on function public.saveat_report_collection(uuid) to authenticated;

create or replace function public.saveat_transition(p_id uuid,p_status text) returns text
language plpgsql security definer set search_path='' as $$
declare v_r public.saveat_reservations; v_l public.saveat_listings; v_listing_id uuid;
begin
 if auth.uid() is null then raise exception 'Accedi per continuare'; end if;
 select listing_id into v_listing_id from public.saveat_reservations where id=p_id;
 select * into v_l from public.saveat_listings where id=v_listing_id for update;
 select * into v_r from public.saveat_reservations where id=p_id for update;
 if v_r.id is null or (v_r.customer_id<>auth.uid() and v_l.owner_id<>auth.uid()) then raise exception 'Prenotazione non accessibile'; end if;
 if v_r.status in ('reserved','confirmed') and v_r.customer_collected_at is null and v_l.pickup_end<=now() then
  update public.saveat_reservations set status='expired',updated_at=now() where id=p_id;
  return 'expired';
 end if;
 if v_r.status=p_status then return p_status; end if;
 if v_r.status not in ('reserved','confirmed') then raise exception 'Prenotazione già conclusa'; end if;
 if p_status='confirmed' then
  if v_l.owner_id<>auth.uid() or v_r.status<>'reserved' then raise exception 'Solo chi pubblica può confermare'; end if;
 elsif p_status='collected' then
  if v_l.owner_id<>auth.uid() or now()<v_l.pickup_start then raise exception 'Il ritiro va confermato da chi pubblica durante la fascia di ritiro'; end if;
 elsif p_status='cancelled' then
  if v_r.customer_collected_at is not null then raise exception 'Ritiro già segnalato: chi pubblica deve confermarlo'; end if;
  update public.saveat_items i set available=i.available+ri.quantity from public.saveat_reservation_items ri where ri.reservation_id=p_id and ri.item_id=i.id;
 else raise exception 'Transizione non ammessa';
 end if;
 update public.saveat_reservations set status=p_status,updated_at=now() where id=p_id;
 return p_status;
end; $$;

create or replace function public.saveat_close_listing(p_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_l public.saveat_listings;
begin
 select * into v_l from public.saveat_listings where id=p_id for update;
 if auth.uid() is null or v_l.owner_id is distinct from auth.uid() then raise exception 'Annuncio non accessibile'; end if;
 -- Cancella le prenotazioni attive e ripristina una sola volta le quantità.
 update public.saveat_items i set available=i.available+q.qty from (
  select ri.item_id,sum(ri.quantity) qty from public.saveat_reservation_items ri join public.saveat_reservations r on r.id=ri.reservation_id
  where r.listing_id=p_id and r.status in ('reserved','confirmed') and r.customer_collected_at is null group by ri.item_id
 ) q where i.id=q.item_id;
 update public.saveat_reservations set status=case when v_l.pickup_end<=now() then 'expired' else 'cancelled' end,updated_at=now() where listing_id=p_id and status in ('reserved','confirmed') and customer_collected_at is null;
 update public.saveat_listings set status='closed' where id=p_id;
end; $$;

-- Scadenza derivata dal pickup_end, anche senza cron: non consente prenotazioni/ritiri tardivi.
create or replace function public.saveat_my_reservations() returns jsonb
language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object(
 'id',r.id,'status',case when r.status in ('reserved','confirmed') and r.customer_collected_at is null and l.pickup_end<=now() then 'expired' else r.status end,
 'customer_name',case when l.owner_id=auth.uid() then coalesce(nullif(trim(c.display_name),''),'Utente Saveat') else null end,'customer_collected_at',r.customer_collected_at,'listing_id',l.id,'title',l.title,'owner_id',l.owner_id,'seller_name',l.seller_name,
 'pickup_start',l.pickup_start,'pickup_end',l.pickup_end,'created_at',r.created_at,
 'items',(select coalesce(jsonb_agg(to_jsonb(ri)),'[]'::jsonb) from public.saveat_reservation_items ri where ri.reservation_id=r.id),
 'pickup',case when l.owner_id=auth.uid() or (r.customer_id=auth.uid() and r.status in ('reserved','confirmed') and l.pickup_end>now()) then (select to_jsonb(p) from public.saveat_pickup p where p.listing_id=l.id) else null end
 ) order by r.created_at desc),'[]'::jsonb)
 from public.saveat_reservations r join public.saveat_listings l on l.id=r.listing_id join public.saveat_profiles c on c.id=r.customer_id
 where auth.uid() is not null and (r.customer_id=auth.uid() or l.owner_id=auth.uid());
$$;

-- Revoca EXECUTE predefinito da PUBLIC su ogni funzione Saveat.
create or replace function public.saveat_search(p_query text default '',p_city text default null,p_page integer default 0,p_size integer default 20) returns jsonb
language sql stable security invoker set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at desc),'[]'::jsonb) from (
  select l.*,
   (select coalesce(jsonb_agg(to_jsonb(i) order by i.name),'[]'::jsonb) from public.saveat_items i where i.listing_id=l.id) saveat_items,
   (select jsonb_build_object('name',m.name,'province',m.province) from public.saveat_municipalities m where m.code=l.municipality_code) saveat_municipalities
  from public.saveat_listings l where l.status='active' and l.pickup_end>now()
   and (p_city is null or l.municipality_code=p_city)
   and exists(select 1 from public.saveat_items i where i.listing_id=l.id and i.available>0)
   and (coalesce(p_query,'')='' or position(lower(left(p_query,100)) in lower(l.title))>0 or exists(
    select 1 from public.saveat_items i where i.listing_id=l.id and i.available>0 and position(lower(left(p_query,100)) in lower(i.name))>0
   ))
  order by l.created_at desc limit least(greatest(p_size,1),20) offset least(greatest(p_page,0),10000)*least(greatest(p_size,1),20)
 ) q;
$$;
do $$ declare f record; begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'saveat_%' loop
  execute format('revoke all on function %s from public, anon, authenticated',f.signature);
 end loop;
end $$;
grant execute on function public.saveat_owns_listing(uuid) to anon,authenticated;
grant execute on function public.saveat_has_reservation(uuid) to anon,authenticated;
grant execute on function public.saveat_search(text,text,integer,integer) to anon,authenticated;
grant execute on function public.saveat_set_profile(text,text,text),public.saveat_create_listing(jsonb,jsonb),public.saveat_reserve(uuid,jsonb,uuid),public.saveat_transition(uuid,text),public.saveat_close_listing(uuid),public.saveat_my_reservations(),public.saveat_report_collection(uuid) to authenticated;

-- Foto degli alimenti pubbliche; indirizzi/contatti non vanno caricati nelle foto.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values('saveat-photos','saveat-photos',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
drop policy if exists saveat_photo_insert on storage.objects;
create policy saveat_photo_insert on storage.objects for insert to authenticated with check(bucket_id='saveat-photos' and split_part(name,'/',1)=(select auth.uid())::text);
drop policy if exists saveat_photo_owner_read on storage.objects;
create policy saveat_photo_owner_read on storage.objects for select to authenticated using(bucket_id='saveat-photos' and split_part(name,'/',1)=(select auth.uid())::text);
